def max_subarray_brute(a: list[int]) -> int:
    best = float("-inf")
    for i in range(len(a)):
        s = 0
        for j in range(i, len(a)):
            s += a[j]
            best = max(best, s)
    return int(best)

def max_subarray(a: list[int]) -> int:
    if not a:
        raise ValueError("empty array")
    best = cur = a[0]
    for x in a[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best
